// Generated by scripts/configure — do not edit by hand.
// Bridges the SDD runtime Go binary (ospec-hooks) into opencode plugin events,
// because opencode has no shell-command hooks. See the generator's
// scripts/lib/target-profiles/opencode-plugin.js for rationale.
import { spawnSync } from "node:child_process";
import { existsSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join, resolve } from "node:path";

const here = dirname(fileURLToPath(import.meta.url));
const isWin = process.platform === "win32";
const EXE = isWin ? ".exe" : "";

export function resolveBinary({ here: pluginDir = here, extension = EXE, exists = existsSync } = {}) {
  // Global plugins live at ~/.config/opencode/plugins; project plugins use .opencode/plugins.
  const globalDistBin = resolve(join(pluginDir, "..", "release", "dist", "ospec-hooks" + extension));
  if (exists(globalDistBin)) {
    return globalDistBin;
  }
  const localDistBin = resolve(join(pluginDir, "..", "..", "release", "dist", "ospec-hooks" + extension));
  if (exists(localDistBin)) {
    return localDistBin;
  }
  // PATH is a developer fallback, never the managed installation source.
  return "ospec-hooks" + extension;
}

export function resolvePluginRoot({ here: pluginDir = here, exists = existsSync } = {}) {
  // The bundle root whose skills/ feed the session-start skill registry,
  // mirroring resolveBinary's global-then-project priority:
  //   - global install: {plugin_dir}/.. keeps skills/ beside plugins/ and release/
  //   - project install: {plugin_dir}/../.. keeps skills/ at the project root
  const globalRoot = resolve(join(pluginDir, ".."));
  if (exists(join(globalRoot, "skills"))) {
    return globalRoot;
  }
  const localRoot = resolve(join(pluginDir, "..", ".."));
  if (exists(join(localRoot, "skills"))) {
    return localRoot;
  }
  // No bundle skills/ found: keep the global root so the binary reports an
  // absolute, actionable skills path instead of resolving against its cwd.
  return globalRoot;
}

function runHook(subcommand, payload, { cwd, env } = {}) {
  const options = {
    input: JSON.stringify(payload),
    encoding: "utf8",
    shell: false,
  };
  // Pin the child to the session workspace: the binary resolves relative bundle
  // paths and the git collaboration guard against its process cwd, which for a
  // global plugin host is the opencode server's, not the workspace.
  if (cwd) {
    options.cwd = cwd;
  }
  if (env) {
    options.env = { ...process.env, ...env };
  }
  return spawnSync(resolveBinary(), [subcommand], options);
}

// outputRedaction tells the guard that this runtime rewrites tool results
// (v2 execute.after), so a non-shell read of a secret needs no prompt; any
// other caller clears an inherited value.
function hookVerdict(toolName, toolInput, directory, outputRedaction = false) {
  const result = runHook(
    "pre-tool-use",
    { tool_name: toolName, tool_input: toolInput || {} },
    { cwd: directory, env: { OSPEC_OUTPUT_REDACTION: outputRedaction ? "1" : "" } },
  );
  if (result.error) {
    throw new Error("[ospec-workflow] pre-tool-use hook failed: " + result.error.message);
  }
  if (result.status !== 0) {
    throw new Error("[ospec-workflow] pre-tool-use hook failed with status " + result.status);
  }
  let verdict = null;
  try {
    const parsed = JSON.parse(result.stdout || "{}");
    verdict = parsed && parsed.hookSpecificOutput;
  } catch (err) {
    throw new Error("[ospec-workflow] pre-tool-use invalid output: " + err.message);
  }
  return verdict;
}

// E1.27: the post-tool-use hook returns the tool result with every secret
// replaced by a marker, or nothing when there is none. When the hook cannot
// run, every string of the result is withheld instead (fail closed).
function withheldResult(value, notice) {
  if (typeof value === "string") {
    return notice;
  }
  if (Array.isArray(value)) {
    return value.map((item) => withheldResult(item, notice));
  }
  if (value && typeof value === "object") {
    return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, withheldResult(item, notice)]));
  }
  return value;
}

// tool_input names the file read, so a .env or credentials file is
// redacted in sensitive-file mode.
function redactedResult(toolName, toolInput, response, directory) {
  let detail;
  try {
    const result = runHook("post-tool-use", { tool_name: toolName, tool_input: toolInput, tool_response: response }, { cwd: directory });
    if (!result.error && result.status === 0) {
      if (!(result.stdout || "").trim()) {
        return null;
      }
      const output = JSON.parse(result.stdout).hookSpecificOutput;
      if (output && output.hookEventName === "PostToolUse" && output.updatedToolOutput !== undefined) {
        return output.updatedToolOutput;
      }
      detail = "invalid output";
    } else {
      detail = result.error ? result.error.message : "status " + result.status;
    }
  } catch (err) {
    detail = err.message;
  }
  return withheldResult(response, "[ospec] Salida retenida: la censura de secretos falló (" + detail + ").");
}

// v1, and any runtime without the native permission API, can only allow
// (return) or block (throw): deny, ask and unknown verdicts collapse to a
// hard block (fail closed).
function blockOrAllow(verdict) {
  if (!verdict || verdict.permissionDecision === "allow") {
    return;
  }
  throw new Error(verdict.permissionDecisionReason || "Blocked by ospec-workflow safety policy");
}

// OpenCode >= 2.0.29 exposes ctx.permission.assert: an ask verdict becomes the
// host's own permission prompt instead of a hard block.
function nativeAsk(ctx) {
  return Boolean(ctx && ctx.permission && typeof ctx.permission.assert === "function");
}

// The permission request carries the guarded tool plus the concrete detail the
// input exposes (command, path) so the prompt shows what is being confirmed;
// metadata.reason surfaces the guard's advisory through the evaluate hook.
function permissionRequest(event, verdict) {
  const input = (event && event.input) || {};
  const detail = [input.command, input.filePath, input.file_path, input.path, input.target_file].find(
    (value) => typeof value === "string" && value,
  );
  const request = {
    sessionID: event && event.sessionID,
    action: "ospec",
    resources: [event && event.tool, detail].filter((value) => typeof value === "string" && value),
    metadata: { reason: (verdict && verdict.permissionDecisionReason) || "" },
  };
  if (
    event &&
    typeof event.messageID === "string" &&
    event.messageID &&
    typeof event.id === "string" &&
    event.id
  ) {
    request.source = { type: "tool", messageID: event.messageID, id: event.id };
  }
  if (event && event.agent) {
    request.agent = event.agent;
  }
  return request;
}

function sessionStart(directory) {
  try {
    // plugin_root tells the binary where the bundle's skills/ live; without it
    // the binary resolves skills/ against the opencode server's cwd.
    runHook(
      "session-start",
      { cwd: directory, plugin_root: resolvePluginRoot() },
      { cwd: directory },
    );
  } catch {
    // session-start is best-effort; never block a session on cache build.
  }
}

// E1.49: the end of a turn runs the Stop hook, which counts it in .ospec/turns
// for the gate fence. Only the root session counts: a subagent's session has
// a parent and ends inside the turn, and a session whose record cannot be read
// does not count either, so a missed turn leaves an answer user-unverified.
async function isRootSession(readSession) {
  try {
    const session = await readSession();
    return Boolean(session && typeof session.id === "string" && !session.parentID);
  } catch {
    return false;
  }
}

function turnEnd(directory, sessionID) {
  try {
    runHook("stop", { cwd: directory, session_id: sessionID }, { cwd: directory });
  } catch {
    // The count is best-effort, like the session trace the hook also writes.
  }
}

// The events that end a turn on OpenCode 2.x.
const TURN_ENDS = new Set(["session.execution.succeeded", "session.execution.failed", "session.execution.interrupted"]);

// v1 entrypoint: OpenCode 1.x (>= 1.18.29) calls server() with the plugin
// context and consumes the returned hooks object.
export const OspecWorkflowPlugin = async ({ directory, client }) => {
  return {
    event: async ({ event }) => {
      if (event && event.type === "session.created") {
        sessionStart(directory);
      }
      const sessionID = event && event.type === "session.idle" && event.properties && event.properties.sessionID;
      if (sessionID && client && client.session && await isRootSession(async () => (await client.session.get({ path: { id: sessionID } })).data)) {
        turnEnd(directory, sessionID);
      }
    },
    "tool.execute.before": async (input, output) => {
      blockOrAllow(hookVerdict(input && input.tool, output && output.args, directory));
    },
    // Not verified live on OpenCode 1.x: the guard keeps asking before reads.
    "tool.execute.after": async (input, output) => {
      if (!output || typeof output !== "object") {
        return;
      }
      const redacted = redactedResult(input && input.tool, undefined, output, directory);
      if (redacted && typeof redacted === "object") {
        Object.assign(output, redacted);
      }
    },
  };
};

// v2 entrypoint: OpenCode 2.x calls setup(ctx); hooks and subscriptions are
// registered through the context and disposed when the plugin unloads.
async function setupOspecWorkflow(ctx) {
  const directory = ctx.location.directory;
  // The host's base policy allows every action, so asserting the ospec action
  // would resolve allow without a prompt; the evaluate hook escalates our own
  // action back to ask and publishes the guard's advisory as the prompt
  // message. "always" cannot silence the guard: it confirms every time.
  if (ctx.permission && typeof ctx.permission.hook === "function") {
    await ctx.permission.hook("evaluate", (evaluation) => {
      if (!evaluation || evaluation.action !== "ospec") {
        return;
      }
      evaluation.effect = "ask";
      const reason = evaluation.metadata && evaluation.metadata.reason;
      if (reason) {
        evaluation.message = reason;
      }
    });
  }
  await ctx.tool.hook("execute.before", async (event) => {
    const verdict = hookVerdict(event && event.tool, event && event.input, directory, true);
    // deny stays a hard block; ask becomes the host's native prompt when the
    // runtime exposes ctx.permission.assert (OpenCode >= 2.0.29).
    if (verdict && verdict.permissionDecision === "ask" && nativeAsk(ctx)) {
      await ctx.permission.assert(permissionRequest(event, verdict));
      return;
    }
    blockOrAllow(verdict);
  });
  // OpenCode 2.x returns event.result after execute.after: replacing it is
  // what the model receives (verified live on 2.0.32).
  await ctx.tool.hook("execute.after", async (event) => {
    if (!event || event.status !== "completed" || event.result === undefined) {
      return;
    }
    const redacted = redactedResult(event.tool, event.input, event.result, directory);
    if (redacted !== null) {
      event.result = redacted;
    }
  });
  const controller = new AbortController();
  void (async () => {
    try {
      for await (const event of ctx.event.subscribe({ signal: controller.signal })) {
        if (event && event.type === "session.created") {
          sessionStart(directory);
        }
        const sessionID = event && TURN_ENDS.has(event.type) && event.data && event.data.sessionID;
        if (sessionID && ctx.session && typeof ctx.session.get === "function" && await isRootSession(() => ctx.session.get({ sessionID }))) {
          turnEnd(directory, sessionID);
        }
      }
    } catch {
      // The subscription ends when the plugin unloads (abort) or the stream fails.
    }
  })();
  return () => controller.abort();
}

export default {
  id: "ospec",
  server: OspecWorkflowPlugin,
  setup: setupOspecWorkflow,
};
